// Emit JSON Schema (draft 2020-12) for the ETK contracts.
// Each file is self-contained: shared sub-schemas live in $defs and enums are
// inlined, so a single file can be pasted into a model's structured-output
// config without sibling references.

import type { Contract, Field } from "./dialect.js";

const DRAFT = "https://json-schema.org/draft/2020-12/schema";
const NOTE_NAME = "note";
const BANNER =
  "GENERATED by tools/generate - do not edit by hand. Source: schemas/etk/*.yaml. Regenerate: just generate.";

type Json = Record<string, unknown>;

function tagDef(c: Contract): Json {
  return { type: "string", enum: c.tags };
}

function relationDef(c: Contract): Json {
  return {
    type: "object",
    properties: {
      type: { type: "string", enum: c.relationTypes },
      target: { type: "string", minLength: 1 },
    },
    required: ["type", "target"],
    additionalProperties: false,
  };
}

function listConstraints(s: Json, f: Field): void {
  if (f.minItems !== undefined) s.minItems = f.minItems;
  if (f.maxItems !== undefined) s.maxItems = f.maxItems;
  if (f.uniqueItems) s.uniqueItems = true;
}

/** Map one IR field to a JSON Schema fragment. */
function fieldSchema(f: Field, c: Contract, memberName?: string): Json {
  switch (f.kind) {
    case "string": {
      const s: Json = { type: "string" };
      if (f.minLength !== undefined) s.minLength = f.minLength;
      if (f.maxLength !== undefined) s.maxLength = f.maxLength;
      if (f.pattern !== undefined) s.pattern = f.pattern;
      return s;
    }
    case "date":
      return { type: "string", pattern: f.pattern ?? "^\\d{4}-\\d{2}-\\d{2}$" };
    case "uri":
      return { type: "string", pattern: f.pattern ?? "^https?://\\S+$" };
    case "boolean":
      return { type: "boolean" };
    case "enum":
      return { type: "string", enum: f.values };
    case "string_list": {
      const items: Json = { type: "string", minLength: 1 };
      if (f.itemPattern !== undefined) items.pattern = f.itemPattern;
      const s: Json = { type: "array", items };
      listConstraints(s, f);
      return s;
    }
    case "tags": {
      const s: Json = { type: "array", items: { $ref: "#/$defs/tag" } };
      listConstraints(s, f);
      if (f.includeTag && memberName) {
        const required = f.includeTag.replace("{noteType}", memberName);
        s.allOf = [{ contains: { const: required } }];
      }
      return s;
    }
    case "links": {
      const s: Json = {
        type: "array",
        items: { type: "string", minLength: 1, pattern: f.itemPattern ?? "^[^\\[\\]]+$" },
      };
      listConstraints(s, f);
      return s;
    }
    case "relations": {
      const s: Json = { type: "array", items: { $ref: "#/$defs/relation" } };
      listConstraints(s, f);
      return s;
    }
    case "tasks": {
      const s: Json = {
        type: "array",
        items: {
          type: "object",
          properties: { text: { type: "string", minLength: 1 }, done: { type: "boolean" } },
          required: ["text", "done"],
          additionalProperties: false,
        },
      };
      listConstraints(s, f);
      return s;
    }
    case "list": {
      const s: Json = { type: "array", items: { $ref: `#/$defs/${f.itemRef}` } };
      listConstraints(s, f);
      return s;
    }
    case "ref":
      return { $ref: `#/$defs/${f.rawType}` };
  }
}

/** Build a strict object schema from a list of fields. */
function objectSchema(
  fields: Field[],
  c: Contract,
  memberName?: string,
  extraProps: Json = {},
  extraRequired: string[] = [],
): Json {
  const properties: Json = {};
  const required: string[] = [];
  for (const f of fields) {
    properties[f.name] = fieldSchema(f, c, memberName);
    if (f.required) required.push(f.name);
  }
  for (const [k, v] of Object.entries(extraProps)) properties[k] = v;
  required.push(...extraRequired);
  return { type: "object", properties, required, additionalProperties: false };
}

/** The note discriminated union as oneOf + its shared $defs. */
function noteUnion(c: Contract): { oneOf: Json[]; defs: Json } {
  const note = c.types.find((t) => t.name === NOTE_NAME);
  if (!note || !note.isUnion) throw new Error("note union not found");
  const oneOf = note.members.map((m) =>
    objectSchema(
      [...note.baseFields, ...m.fields],
      c,
      m.name,
      { [note.discriminator!]: { const: m.name } },
      [note.discriminator!],
    ),
  );
  return { oneOf, defs: { tag: tagDef(c), relation: relationDef(c) } };
}

export function emitTagSchema(c: Contract): string {
  const doc: Json = {
    $schema: DRAFT,
    $id: "etk-tag.schema.json",
    $comment: BANNER,
    title: "EtkTag",
    description: "A valid ETK ontology tag (closed enum; no leading '#').",
    type: "string",
    enum: c.tags,
  };
  return JSON.stringify(doc, null, 2) + "\n";
}

export function emitNoteSchema(c: Contract): string {
  const note = c.types.find((t) => t.name === NOTE_NAME)!;
  const { oneOf, defs } = noteUnion(c);
  const doc: Json = {
    $schema: DRAFT,
    $id: "etk-note.schema.json",
    $comment: BANNER,
    title: "EtkNote",
    description: note.description,
    oneOf,
    $defs: defs,
  };
  return JSON.stringify(doc, null, 2) + "\n";
}

export function emitProposalSchema(c: Contract): string {
  const { oneOf, defs: noteDefs } = noteUnion(c);
  const get = (name: string) => c.types.find((t) => t.name === name)!;
  const defs: Json = {
    tag: noteDefs.tag,
    relation: noteDefs.relation,
    note: { oneOf },
    proposal_source: objectSchema(get("proposal_source").fields, c),
    proposal: objectSchema(get("proposal").fields, c),
  };
  const env = get("proposal_envelope");
  const doc: Json = {
    $schema: DRAFT,
    $id: "etk-proposal.schema.json",
    $comment: BANNER,
    title: "EtkProposalEnvelope",
    description: env.description,
    ...objectSchema(env.fields, c),
    $defs: defs,
  };
  return JSON.stringify(doc, null, 2) + "\n";
}
